struct vector4d {
  float x, y, z, w;
} __attribute__((aligned(16)));

struct frame_info {
  float age;
  int ifl_frame_boost;
  int ifl_frame_locked;
};

struct vector3d {
  float x, y, z;
};

struct instance_render_info {
  float number_of_faces_to_attempt;
  vector4d local_to_world[4];
  unsigned int force_flags;
  unsigned int color_scale;
  float camera_relative_rotation;
  frame_info frame_time_info;
  void *my_region;
  float particle_scale;
  void *my_light_set;
  void *alt_materials;
  int frame;
  vector3d render_scale;

  bool operator<(const instance_render_info& iri) const { return frame < iri.frame; }
} __attribute__((aligned(16)));

extern "C" void partial_sort(instance_render_info *, instance_render_info *,
                             instance_render_info *, instance_render_info *)
  __asm__("__partial_sort__H2ZP20instance_render_infoZ20instance_render_info_X01X01X01PX11_v");
extern "C" instance_render_info *unguarded_partition(
    instance_render_info *, instance_render_info *,
    const instance_render_info &, instance_render_info *)
  __asm__("__unguarded_partition__H2ZP20instance_render_infoZ20instance_render_info_X01X01X11_X01");

template <class _Tp>
inline const _Tp& __median(const _Tp& __a, const _Tp& __b, const _Tp& __c) {
  if (__a < __b)
    if (__b < __c)
      return __b;
    else if (__a < __c)
      return __c;
    else
      return __a;
  else if (__a < __c)
    return __a;
  else if (__b < __c)
    return __c;
  else
    return __b;
}

extern "C" void introsort_loop(instance_render_info *, instance_render_info *,
                                instance_render_info *, int)
  __asm__("__introsort_loop__H3ZP20instance_render_infoZ20instance_render_infoZi_X01X01PX11X21_v");

void introsort_loop(instance_render_info* __first,
                    instance_render_info* __last,
                    instance_render_info*, int __depth_limit) {
  while (__last - __first > 16) {
    if (__depth_limit == 0) {
      partial_sort(__first, __last, __last, (instance_render_info*) 0);
      return;
    }
    --__depth_limit;
    instance_render_info* __cut = unguarded_partition(
      __first, __last,
      instance_render_info(__median(*__first,
                                   *(__first + (__last - __first)/2),
                                   *(__last - 1))),
      (instance_render_info*) 0);
    introsort_loop(__cut, __last, (instance_render_info*) 0, __depth_limit);
    __last = __cut;
  }
}
